import csv
import json
from datetime import date, datetime
from pathlib import Path

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

sources = [
    ('source_a', Path('/data/source_a/users.json')),
    ('source_b', Path('/data/source_b/users.csv')),
    ('source_c', Path('/data/source_c/users.parquet')),
]
priority = [name for name, _ in sources]
aliases = {
    'user_id': ('user_id', 'id', 'userId'),
    'name': ('full_name', 'name', 'userName'),
    'email': ('email', 'email_address'),
    'created_date': ('registration_date', 'created_at', 'joined'),
    'status': ('status', 'is_active', 'active'),
}
output_fields = ('user_id', 'name', 'email', 'created_date', 'status')


def is_missing(value):
    if value is None:
        return True
    try:
        result = pd.isna(value)
        return bool(result) if not hasattr(result, '__len__') else False
    except (TypeError, ValueError):
        return False


def get_value(record, names):
    for name in names:
        if name in record and not is_missing(record[name]) and record[name] != '':
            return record[name]
    return None


def normalize_status(value):
    if isinstance(value, bool):
        return 'active' if value else 'inactive'
    text = str(value).strip().lower()
    if text in {'true', '1', 'yes', 'active'}:
        return 'active'
    if text in {'false', '0', 'no', 'inactive'}:
        return 'inactive'
    return str(value).strip()


def normalize_date(value):
    if isinstance(value, (datetime, date)):
        return value.strftime('%Y-%m-%d')
    return pd.to_datetime(value, errors='raise').strftime('%Y-%m-%d')


def normalize_record(record):
    normalized = {}
    user_id = get_value(record, aliases['user_id'])
    if user_id is None:
        raise ValueError(f'Record is missing user_id: {record!r}')
    normalized['user_id'] = int(user_id)
    for field in output_fields[1:]:
        value = get_value(record, aliases[field])
        if value is None:
            continue
        if field == 'created_date':
            value = normalize_date(value)
        elif field == 'status':
            value = normalize_status(value)
        else:
            value = str(value)
        normalized[field] = value
    return normalized


def read_records(source_name, path):
    if source_name == 'source_a':
        return json.loads(path.read_text(encoding='utf-8'))
    if source_name == 'source_b':
        with path.open(newline='', encoding='utf-8') as handle:
            return list(csv.DictReader(handle))
    return pd.read_parquet(path, engine='pyarrow').to_dict(orient='records')

records_by_source = {}
for source_name, path in sources:
    records = [normalize_record(record) for record in read_records(source_name, path)]
    source_records = {}
    for record in records:
        user_id = record['user_id']
        if user_id in source_records:
            raise ValueError(f'Duplicate user_id {user_id} in {source_name}')
        source_records[user_id] = record
    records_by_source[source_name] = source_records

all_user_ids = sorted({user_id for records in records_by_source.values() for user_id in records})
merged_rows = []
conflicts = []

for user_id in all_user_ids:
    per_source = {
        source_name: records_by_source[source_name][user_id]
        for source_name in priority
        if user_id in records_by_source[source_name]
    }
    merged = {'user_id': user_id}
    for field in output_fields[1:]:
        field_values = {
            source_name: record[field]
            for source_name, record in per_source.items()
            if field in record
        }
        if field_values:
            selected_source = next(source for source in priority if source in field_values)
            selected_value = field_values[selected_source]
            merged[field] = selected_value
            distinct_values = list(dict.fromkeys(field_values.values()))
            if len(distinct_values) > 1:
                conflicts.append({
                    'user_id': user_id,
                    'field': field,
                    'values': field_values,
                    'selected': selected_value,
                })
    merged_rows.append(merged)

schema = pa.schema([
    ('user_id', pa.int64()),
    ('name', pa.string()),
    ('email', pa.string()),
    ('created_date', pa.string()),
    ('status', pa.string()),
])
columns = {
    field: pa.array([row.get(field) for row in merged_rows], type=field_type)
    for field, field_type in zip(schema.names, schema.types)
}
table = pa.table(columns, schema=schema)
pq.write_table(table, '/app/merged_users.parquet')

conflict_report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
Path('/app/conflicts.json').write_text(
    json.dumps(conflict_report, indent=2, ensure_ascii=False) + '\n',
    encoding='utf-8',
)

print(f'Wrote {len(merged_rows)} merged users to /app/merged_users.parquet')
print(f'Wrote {len(conflicts)} conflicts to /app/conflicts.json')
